WITH d AS (INSERT INTO project_documents(project_id, entity_kind, entity_name, content, content_hash, bytes, revision, updated_at, updated_by) SELECT $1, 'index', r.value, 'проба самотеста: реестр вопросов', 'probe-selftest', 0, 1, 1757000000000, 'probe-selftest' FROM scheme($1) r WHERE r.role = 'register.questions' ON CONFLICT DO NOTHING RETURNING 1) INSERT INTO project_document_cells(project_id, entity_kind, entity_name, block_ord, row_ord, col, raw, value) SELECT $1, 'index', r.value, 9990, 1, c.col, c.raw, c.raw FROM scheme($1) r, (VALUES (0, 'Q-9996'), (1, 'решено владельцем, ждём')) AS c(col, raw) WHERE r.role = 'register.questions'
